"""Generate engine/constants.js from SIMULATION-MATHS.md section 12 and the sheet README.

ENGINE.md rule 1: every number the engine uses comes from section 12 or the sheet.
The engine imports this generated module, so it runs unchanged in Node and a browser.
Stops if section 12 and the sheet disagree (ENGINE.md rule 4).

A constant whose section 12 description contains UNVERIFIED is listed in
CONSTANTS.UNVERIFIED and flagged in a comment, so a placeholder never quietly passes for a
real number.

Usage: python scripts/export_constants.py
"""

import json
import re
import sys
from pathlib import Path

from openpyxl import load_workbook

ROOT = Path(__file__).resolve().parent.parent
DOC_PATH = ROOT / "SIMULATION-MATHS.md"
XLSX_PATH = ROOT / "chapter1_decisions_v34.xlsx"
OUT_PATH = ROOT / "engine" / "constants.js"

# Sheet README label -> baseline key
BASELINE_ROWS = {
    "Starting gross salary": "SALARY_GROSS_START",
    "Starting in-hand": "SALARY_NET_START",
    "Starting age": "AGE_START",
    "Starting net worth": "NET_WORTH_START",
}
ROW = re.compile(r"^\| `([A-Z_]+)` \| ([-\d.]+) \|(.*)$", re.M)


def read_section_12():
    text = DOC_PATH.read_text(encoding="utf-8")
    section = re.search(r"^## 12\..*?(?=^## )", text, re.S | re.M)
    if not section:
        sys.exit("Section 12 not found in " + DOC_PATH.name)
    constants, unverified = {}, []
    for name, value, controls in ROW.findall(section.group(0)):
        constants[name] = float(value) if "." in value else int(value)
        if "UNVERIFIED" in controls:
            unverified.append(name)
    return constants, sorted(unverified)


def read_baseline():
    ws = load_workbook(XLSX_PATH, read_only=True)["README"]
    baseline = {}
    for label, value in ws.iter_rows(values_only=True):
        if label in BASELINE_ROWS:
            number = re.match(r"^\s*([\d,]+)", str(value))
            if not number:
                sys.exit(f"README {label!r} has no number: {value!r}")
            baseline[BASELINE_ROWS[label]] = int(number.group(1).replace(",", ""))
    missing = set(BASELINE_ROWS.values()) - set(baseline)
    if missing:
        sys.exit(f"Sheet README is missing: {sorted(missing)}")
    return baseline


def main():
    constants, unverified = read_section_12()
    baseline = read_baseline()

    for key, value in baseline.items():
        if key in constants and constants[key] != value:
            sys.exit(f"{key}: section 12 says {constants[key]}, sheet README says {value}. Stop and ask.")
        constants[key] = value

    constants["UNVERIFIED"] = unverified
    body = json.dumps(dict(sorted(constants.items())), indent=2)
    warnings = "".join(
        f"// UNVERIFIED placeholder: {name} = {constants[name]}. Not a real figure. See section 14.\n"
        for name in unverified
    )
    OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
    OUT_PATH.write_text(
        "// Generated by scripts/export_constants.py from SIMULATION-MATHS.md section 12\n"
        f"// and the {XLSX_PATH.name} README. Do not edit by hand.\n"
        f"{warnings}\n"
        f"const CONSTANTS = Object.freeze({body});\n\nexport default CONSTANTS;\n",
        encoding="utf-8",
        newline="\n",
    )
    print(f"Wrote {len(constants) - 1} constants to {OUT_PATH.relative_to(ROOT)}. "
          f"UNVERIFIED: {', '.join(unverified) or 'none'}")


if __name__ == "__main__":
    main()
